<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$base=realpath(__DIR__.'/../uploads');$type=$_GET['type']??'all';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rel=str_replace(['..','\\'],['','/'],(string)($_POST['file']??''));$target=realpath(__DIR__.'/../'.$rel);if($base&&$target&&str_starts_with($target,$base.DIRECTORY_SEPARATOR)&&is_file($target))unlink($target);header('Location: media.php');exit;}$files=[];if($base){foreach(['image','audio'] as $dir){if($type!=='all'&&$type!==$dir)continue;$path=$base.DIRECTORY_SEPARATOR.$dir;if(is_dir($path)){foreach(scandir($path) as $f){if($f!=='.'&&$f!=='..'&&is_file($path.DIRECTORY_SEPARATOR.$f))$files[]=['path'=>'uploads/'.$dir.'/'.$f,'type'=>$dir,'name'=>$f,'size'=>filesize($path.DIRECTORY_SEPARATOR.$f)];}}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Media Library</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Media Library</h1><p><a href="upload.php">Upload media</a> · <a href="?type=all">All</a> · <a href="?type=image">Images</a> · <a href="?type=audio">Audio</a> · <a href="dashboard.php">Dashboard</a></p><div class="grid"><?php foreach($files as $file):?><article class="card"><p><strong><?=e($file['type'])?></strong></p><p><?=e($file['name'])?></p><p class="muted"><?=e(number_format($file['size']/1024,1))?> KB</p><form method="post" onsubmit="return confirm('Delete this file?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="file" value="<?=e($file['path'])?>"><button>Delete</button></form></article><?php endforeach;?></div><?php if(!$files):?><p class="muted">No media files found.</p><?php endif;?></main></body></html>
